import{_ as a}from"./chunks/daily-2026-08-11-execution-authority-ordered-work-figure.CAfgnFyW.js";import{_ as r,C as i,o,c as n,E as s,a2 as d}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"Digital Employees Need an Explicit Execution-Authority Boundary","description":"","frontmatter":{"title":"Digital Employees Need an Explicit Execution-Authority Boundary","date":"2026-08-11","column":"digital-employee","category":"daily","summary":"Scheduled or received work proves demand, not permission to execute. A Digital Employee runtime should separate queue arrival from explicit worker claim, governed Running state and terminal evidence, while introducing concurrency only through explicit execution identities.","sources":["research/analysis/Q-20260811-01-execution-authority-ordered-work.md","research/reading/Q-20260811-01-ordered-local-work-queue.md"],"item_id":"Q-20260811-01","lifecycle":"Published","source_research_object":"research/analysis/Q-20260811-01-execution-authority-ordered-work.md","source_reading_result":"research/reading/Q-20260811-01-ordered-local-work-queue.md","cover":"/assets/covers/daily-2026-08-11-execution-authority-ordered-work.webp","visualization":"/assets/covers/daily-2026-08-11-execution-authority-ordered-work-figure.svg","visualization_decision":"Required — dedicated editorial cover plus a separate ordered-lane explanatory figure","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"en/digital-employee/2026-08-11-execution-authority-ordered-work.md","filePath":"en/digital-employee/2026-08-11-execution-authority-ordered-work.md","lastUpdated":1786455324000}'),c={name:"en/digital-employee/2026-08-11-execution-authority-ordered-work.md"};function l(u,e,h,p,m,g){const t=i("ArticleCover");return o(),n("div",null,[s(t,{image:"/assets/covers/daily-2026-08-11-execution-authority-ordered-work.webp",kicker:"Digital Employee · Daily Research",title:"Digital Employees Need an Explicit Execution-Authority Boundary",summary:"Scheduled or received work proves demand, not permission to execute. A Digital Employee runtime should separate queue arrival from explicit worker claim, governed Running state and terminal evidence, while introducing concurrency only through explicit execution identities.",version:"Q-20260811-01",status:"Daily Runtime V5 · 2026-08-11",languageHref:"/zh/digital-employee/2026-08-11-execution-authority-ordered-work",languageLabel:"中文"}),e[0]||(e[0]=d('<h1 id="digital-employees-need-an-explicit-execution-authority-boundary" tabindex="-1">Digital Employees Need an Explicit Execution-Authority Boundary <a class="header-anchor" href="#digital-employees-need-an-explicit-execution-authority-boundary" aria-label="Permalink to &quot;Digital Employees Need an Explicit Execution-Authority Boundary&quot;">​</a></h1><p>A timer firing, a user request arriving, or a queue entry existing does not mean a Digital Employee is authorized to begin side effects. The central runtime problem is therefore not only scheduling; it is deciding when received intent becomes <strong>execution authority</strong>.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>GitHub Copilot CLI 1.0.79 documents a useful boundary: prompts, shell commands and supported slash commands can arrive while a local-session task is already running, but they are queued and execute in order after the current task finishes. The same release separately supports multiple concurrent sessions. That combination is important: ordering is preserved inside an explicit execution identity, while concurrency is introduced by creating separate identities rather than by allowing hidden overlap inside one lane.</p><p>The Research Center judgment is stronger than “use a queue.” A production Digital Employee runtime should model at least <code>Received/Scheduled → Queued → Claimed → Running → Terminal</code>. The transition to <strong>Claimed</strong> is the authority boundary. A scheduler wake is demand; a worker claim is permission to execute.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>The primary source is the maintainer-published GitHub Copilot CLI 1.0.79 changelog commit dated 2026-08-10:</p><ul><li><a href="https://github.com/github/copilot-cli/commit/ef627e1baad937d3c8da45f8a5541c6fc3c97b6a" target="_blank" rel="noreferrer">https://github.com/github/copilot-cli/commit/ef627e1baad937d3c8da45f8a5541c6fc3c97b6a</a></li></ul><p>Production consumes only the completed same-day Research Object <code>Q-20260811-01</code> and its Reading Result. The changelog establishes released behavior but does not disclose the internal queue data structure or durable persistence semantics.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The release documents three related mechanisms. First, new local-session work may be queued while current work continues; arrival and execution are therefore separate events. Second, multiple concurrent sessions are supported, so ordering is bounded by session identity rather than presented as one global queue. Third, MCP and language-server startup failures caused by the sandbox are turned into bounded failures instead of indefinite stalls, and <code>/sandbox policy</code> exposes effective policy rather than only configured intent.</p><p>Together these mechanisms point to a runtime discipline: one lane should have one current authority holder, blocking dependencies need bounded failure, and operators need evidence of the policy that was actually applied.</p><p><img src="'+a+'" alt="Ordered-lane execution-authority figure"></p><p><em>Figure 1. After Received and Scheduled work enters Queued, only an explicit Worker Claim grants execution authority. Source: Research Center synthesis based on the cited primary sources.</em></p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Runtime fact</th><th>What it proves</th><th>What it does <strong>not</strong> prove</th><th>Evidence class</th></tr></thead><tbody><tr><td>Timer fired / request arrived</td><td>Work exists</td><td>Permission to mutate state</td><td>Research Center interpretation from documented queue behavior</td></tr><tr><td>Item is queued</td><td>Work has an ordered position</td><td>Worker ownership or live progress</td><td>Documented behavior + interpretation</td></tr><tr><td>Worker explicitly claimed item</td><td>One execution identity owns the lane</td><td>Business success</td><td>Research Center architecture proposal</td></tr><tr><td>Running</td><td>Claimed work is active under a lease</td><td>Completion or freshness forever</td><td>Research Center architecture proposal</td></tr><tr><td>Terminal evidence</td><td>Lane can be released under a governed rule</td><td>Exactly-once external side effects</td><td>Research Center architecture proposal</td></tr><tr><td>Multiple sessions</td><td>Explicit concurrency boundaries exist</td><td>Global resource arbitration</td><td>Documented capability; arbitration unknown</td></tr></tbody></table><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>The dangerous design is to overload <code>Running</code>. If a scheduler changes a task to Running before any worker has actually claimed it, an operations page can display “working” while no execution is happening. The inverse is equally dangerous: if a later timer starts another task because its scheduled time has arrived, two nominal stages can run concurrently even though the earlier stage has not closed.</p><p>A safer model separates facts. <code>Wake Received</code> records that a scheduled trigger actually fired. <code>Queued</code> records pending intent. <code>Worker Claimed</code> records execution authority. <code>Running</code> is a renewable execution lease. A typed terminal state closes the lane and permits the next due item to be considered.</p><p>Concurrency should sit above this model, not inside it. Separate sessions, workers or workspaces can each own deterministic local ordering. Cross-lane side effects then require an explicit synchronization or custody contract rather than accidental overlap.</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><p>For Digital Employee platforms, persist scheduler receipts and worker claims independently. Treat a scheduled time as a wake signal only. The Process Manager should grant one ordered lane at a time unless a separate execution identity has been explicitly created.</p><p>For CodeFlowMu, task arrival from ADMIN/PM and a scheduled Runtime wake should remain queue facts. The UI should show <code>Scheduled/Received</code>, <code>Waiting</code>, <code>Claimed</code>, <code>Running</code> and terminal states separately so an execution slot cannot masquerade as live worker progress. Startup dependencies such as MCP initialization should have bounded leases and explicit failure evidence.</p><p>For TMPA, the mechanism is useful evidence for distinguishing intent, custody, execution authority and terminal evidence, but one product changelog does not justify a protocol-level queue or persistence rule by itself.</p><h2 id="boundaries-and-uncertainty" tabindex="-1">Boundaries and uncertainty <a class="header-anchor" href="#boundaries-and-uncertainty" aria-label="Permalink to &quot;Boundaries and uncertainty&quot;">​</a></h2><p>The source does not establish queue durability across restart, queue capacity, priority, starvation behavior, deduplication or failed-item semantics. It also does not define resource arbitration between concurrent sessions. Therefore the Research Center adopts the <strong>ordering principle</strong>, not an unsupported claim that Copilot CLI already provides restart-safe or exactly-once queue processing.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><p>A product-grade runtime should test crash points between wake receipt, queue persistence, worker claim, tool start and terminal evidence. It should also define which terminal states release the next item after cancellation or partial external side effects, and whether execution authority belongs to one employee-wide lane or multiple role/workspace-scoped lanes.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The header cover uses queued execution chambers and one admitted lane to represent the execution-authority boundary. The figure embedded in the Observation section carries the ordered state model and bilingual labels. Both are Research Center originals; no vendor artwork or invented quantitative data is used.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>GitHub, Copilot CLI 1.0.79 maintainer changelog commit <code>ef627e1baad937d3c8da45f8a5541c6fc3c97b6a</code>, 2026-08-10: <a href="https://github.com/github/copilot-cli/commit/ef627e1baad937d3c8da45f8a5541c6fc3c97b6a" target="_blank" rel="noreferrer">https://github.com/github/copilot-cli/commit/ef627e1baad937d3c8da45f8a5541c6fc3c97b6a</a></li><li>Research Center Research Object: <code>research/analysis/Q-20260811-01-execution-authority-ordered-work.md</code></li><li>Research Center Reading Result: <code>research/reading/Q-20260811-01-ordered-local-work-queue.md</code></li></ol><blockquote><p>Publication status: Released after the Publication gate; article content is unchanged from the completed Production Candidate.</p></blockquote>',33))])}const x=r(c,[["render",l]]);export{f as __pageData,x as default};
